using System.Text.Json;
using System.Text.Json.Nodes;
using SirLocked.Api.Models;

namespace SirLocked.Api.Services.PuzzleKinds;

/// <summary>
/// What the AI may decide for an optional interactive puzzle of an OPEN_COOP_1 case: its kind and the words the
/// player reads. Everything else (geometry, the answer, the reveal) is generated by the kind itself on the server.
/// </summary>
public static class PuzzleKindAuthoring
{
    /// <summary>Kinds whose answer is free (the server makes one up).</summary>
    public static readonly IReadOnlyList<string> FreeKinds =
        ["torn_paper", "lockpick", "music_box", "gear_train", "balance_scale", "tilt_maze", "reagent_mix"];

    /// <summary>Kinds whose answer must come from the approved truth (see <c>TruthBoundPuzzleAnswers</c>).</summary>
    public static readonly IReadOnlyList<string> TruthBoundKinds = ["fingerprint", "doc_forgery", "parallax_code"];

    /// <summary>The text params the AI may write per kind (read by the frontend module); nothing that moves the answer.</summary>
    private static readonly IReadOnlyDictionary<string, IReadOnlyList<string>> AuthoredKeys =
        new Dictionary<string, IReadOnlyList<string>>(StringComparer.Ordinal)
        {
            ["torn_paper"] = ["doc", "note", "find"],
            ["lockpick"] = ["note"],
            ["music_box"] = ["quote"],
            ["gear_train"] = [],
            ["balance_scale"] = [],
            ["tilt_maze"] = [],
            ["reagent_mix"] = ["find", "testimony", "targetName"],
            ["fingerprint"] = ["note", "testimony", "surface", "place"],
            ["doc_forgery"] = ["doc"],
            ["parallax_code"] = []
        };

    public static IReadOnlyList<string> AllowedAuthoredKeys(string? kind) =>
        kind is not null && AuthoredKeys.TryGetValue(kind, out var keys) ? keys : [];

    /// <summary>
    /// The kinds the AI may pick for a puzzle whose reward is <paramref name="rewardTraceId"/>: every free kind, plus
    /// the truth-bound ones the truth can answer for that trace.
    /// </summary>
    public static IReadOnlyList<string> OfferedKinds(CaseTruthPackage truth, string? rewardTraceId) =>
        FreeKinds.Concat(TruthBoundKinds.Where(kind => TruthBoundPuzzleAnswers.CanOffer(kind, truth, rewardTraceId))).ToList();

    /// <summary>
    /// Checks the kind and the authored words of every interactive puzzle in the content. Errors name their path,
    /// e.g. "puzzles.puzzle-01.authored.pieceCount", so a scoped repair can fix just that field.
    /// </summary>
    public static void Check(
        string puzzleId, string? kind, string? authored, IReadOnlyCollection<string> offered, ICollection<string> errors)
    {
        if (string.IsNullOrWhiteSpace(kind) || !offered.Contains(kind))
        {
            var reason = kind is not null && TruthBoundKinds.Contains(kind)
                ? $"PuzzleKindNotSupportedByTruth puzzles.{puzzleId}.kind: pick another kind; the truth has no fact for {kind}."
                : $"PROJECTION_PUZZLE puzzles.{puzzleId}.kind: pick one of {string.Join(", ", offered)}.";
            errors.Add(reason);
            return;
        }
        JsonObject words;
        try { words = Parse(authored); }
        catch (JsonException)
        {
            errors.Add($"PROJECTION_PUZZLE puzzles.{puzzleId}.authored: must be a JSON object.");
            return;
        }
        var allowed = AllowedAuthoredKeys(kind);
        foreach (var (key, _) in words)
            if (!allowed.Contains(key))
                errors.Add($"PROJECTION_PUZZLE puzzles.{puzzleId}.authored.{key}: not a text field of {kind}"
                           + (allowed.Count == 0 ? " (this kind takes no authored text)." : $" (allowed: {string.Join(", ", allowed)})."));
    }

    public static JsonObject Parse(string? authored) =>
        string.IsNullOrWhiteSpace(authored)
            ? new JsonObject()
            : JsonNode.Parse(authored) as JsonObject ?? throw new JsonException("authored is not an object");
}
